<?php
require_once __DIR__.'/includes/config.php';
if(empty($_SESSION['guardian_login'])||empty($_SESSION['guardian_id'])){header('Location: guardian-login.php');exit;}
$students=[];$error='';$data=[];
try {
 $q=$dbh->prepare('SELECT s.StudentId,s.StudentName,s.RollId,s.Gender,s.DOB,c.ClassName,c.Section FROM srms_guardian_students gs JOIN tblstudents s ON s.StudentId=gs.student_id LEFT JOIN tblclasses c ON c.id=s.ClassId WHERE gs.guardian_id=? ORDER BY s.StudentName');$q->execute([(int)$_SESSION['guardian_id']]);$students=$q->fetchAll();
 foreach($students as $s){$id=(int)$s['StudentId'];$data[$id]=['attendance'=>[],'results'=>[],'exams'=>[]];try{$q=$dbh->prepare('SELECT attendance_date,status FROM srms_attendance WHERE student_id=? ORDER BY attendance_date DESC LIMIT 20');$q->execute([$id]);$data[$id]['attendance']=$q->fetchAll();}catch(Throwable $ignore){}try{$q=$dbh->prepare('SELECT r.marks,r.PostingDate,sub.SubjectName,r.AcademicYear,r.Term,r.ExamType FROM tblresult r JOIN tblsubjects sub ON sub.id=r.SubjectId WHERE r.StudentId=? AND r.Published=1 ORDER BY r.PostingDate DESC LIMIT 50');$q->execute([$id]);$data[$id]['results']=$q->fetchAll();}catch(Throwable $ignore){}try{$q=$dbh->prepare("SELECT title,exam_date,start_time,end_time,room,term FROM srms_examinations WHERE class_id=? AND status='published' AND exam_date>=CURDATE() ORDER BY exam_date,start_time LIMIT 30");$q->execute([(int)$s['ClassId']]);$data[$id]['exams']=$q->fetchAll();}catch(Throwable $ignore){}}
} catch(Throwable $e){error_log('Guardian dashboard: '.$e->getMessage());$error='Student portal data is unavailable.';}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#17365d"><link rel="manifest" href="manifest.webmanifest"><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/srms-responsive.css"><title>Guardian Dashboard | <?php echo e(srms_school_name($dbh));?></title><style>body{padding:14px;background:#f5f7fa}.wrap{max-width:1000px;margin:auto}.child{background:white;border:1px solid #ddd;border-radius:8px;padding:16px;margin:12px 0}</style></head><body><div class="wrap"><div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap"><h2><?php echo e(srms_school_name($dbh));?> · Guardian Dashboard</h2><a class="btn btn-default" href="guardian-logout.php">Sign out</a></div><p>Signed in as <?=e($_SESSION['guardian_email']??'guardian')?>. Only records linked by the school are shown.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php foreach($students as $s):$id=(int)$s['StudentId'];?><section class="child"><h3><?=e($s['StudentName'])?></h3><p><strong>Registration number:</strong> <?=e($s['RollId'])?> &nbsp; <strong>Class:</strong> <?=e(($s['ClassName']??'').' '.($s['Section']??''))?></p><h4>Recent attendance</h4><?php if($data[$id]['attendance']):?><div class="table-responsive"><table class="table table-condensed"><thead><tr><th>Date</th><th>Status</th></tr></thead><tbody><?php foreach($data[$id]['attendance'] as $a):?><tr><td><?=e($a['attendance_date'])?></td><td><?=e(ucfirst($a['status']))?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p>No attendance records are available yet.</p><?php endif;?><h4>Published results</h4><?php if($data[$id]['results']):?><div class="table-responsive"><table class="table table-condensed"><thead><tr><th>Subject</th><th>Marks</th><th>Exam</th><th>Year / Term</th></tr></thead><tbody><?php foreach($data[$id]['results'] as $r):?><tr><td><?=e($r['SubjectName'])?></td><td><?=e($r['marks'])?></td><td><?=e($r['ExamType']??'')?></td><td><?=e(($r['AcademicYear']??'').' / '.($r['Term']??''))?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p>No published results are available.</p><?php endif;?><h4>Upcoming published examinations</h4><?php if($data[$id]['exams']):?><div class="table-responsive"><table class="table table-condensed"><thead><tr><th>Date</th><th>Examination</th><th>Time</th><th>Room</th></tr></thead><tbody><?php foreach($data[$id]['exams'] as $x):?><tr><td><?=e($x['exam_date'])?></td><td><?=e($x['title'])?></td><td><?=e(substr($x['start_time'],0,5).'–'.substr($x['end_time'],0,5))?></td><td><?=e($x['room'])?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p>No upcoming published examinations.</p><?php endif;?></section><?php endforeach;?><?php if(!$students):?><div class="alert alert-info">No students are linked to this account. Contact the school office.</div><?php endif;?><script>if('serviceWorker' in navigator){navigator.serviceWorker.register('./service-worker.js').catch(function(){})}</script></div></body></html>
